export function buklodCollectibleNames(characterId: BuklodCharacterWorldId, level: number): readonly [string, string, string, string, string] {
  const safe = Math.max(1, Math.min(20, Math.floor(Number(level) || 1)));
  return BUKLOD_CHARACTER_COLLECTIBLE_ITEMS[characterId][safe - 1];
}

export function buklodCollectibleName(
  characterId: BuklodCharacterWorldId,
  level: number,
  itemIndex: number,
): string {
  const names = buklodCollectibleNames(characterId, level);
  const idx = Math.max(1, Math.min(5, Math.floor(Number(itemIndex) || 1))) - 1;
  return names[idx];
}

export function buklodStageMasteryBadge(characterId: BuklodCharacterWorldId, level: number): string {
  const safe = Math.max(1, Math.min(20, Math.floor(Number(level) || 1)));
  return BUKLOD_CHARACTER_BADGES[characterId].stageMastery[safe - 1];
}

export function buklodCharacterEraForLevel(level: number) {
  const safe = Math.max(1, Math.min(20, Math.floor(Number(level) || 1)));
  return BUKLOD_CHARACTER_ERAS.find((era) => safe >= era.levels[0] && safe <= era.levels[1]) ?? BUKLOD_CHARACTER_ERAS[0];
}

